/*
 * LinkPill styles, shared by the React and HTML shells.
 *
 * Base rules use hex colours and inline-block only, so an old engine (Safari 9)
 * that cannot parse the @supports block still gets a legible, bordered link.
 * The @supports block adds tinted backgrounds and borders. Dark mode follows
 * the `.dark` class the rest of the registry uses.
 */

.link-pill {
  --link-pill-tint: #525252;
  display: inline-block;
  max-width: 100%;
  color: inherit;
  text-decoration: none;
}

.link-pill--mention {
  --link-pill-tint: #6d28d9;
}

.link-pill--file {
  --link-pill-tint: #0369a1;
}

.link-pill--location {
  --link-pill-tint: #0e7490;
}

.link-pill--url {
  --link-pill-tint: #525252;
}

.dark .link-pill--mention {
  --link-pill-tint: #a78bfa;
}

.dark .link-pill--file {
  --link-pill-tint: #38bdf8;
}

.dark .link-pill--location {
  --link-pill-tint: #2dd4bf;
}

.dark .link-pill--url {
  --link-pill-tint: #a3a3a3;
}

.link-pill:focus-visible {
  outline: 2px solid #6d28d9;
  outline: 2px solid var(--link-pill-tint);
  outline-offset: 2px;
}

.link-pill__icon,
.link-pill__avatar {
  display: inline-block;
  width: 1em;
  height: 1em;
  margin-right: 0.35em;
  vertical-align: -0.125em;
  color: var(--link-pill-tint);
}

.link-pill__avatar {
  border-radius: 9999px;
  object-fit: cover;
}

.link-pill__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Inline (prose): wraps like text, never truncates. */
.link-pill--inline {
  text-decoration: underline;
  text-decoration-color: var(--link-pill-tint);
  text-underline-offset: 0.2em;
}

/* Chip (chat): one line, label cut at about 24 characters. The full label is
   still in the DOM, so it stays the accessible name. */
.link-pill--chip {
  padding: 0 0.6em;
  border: 1px solid var(--link-pill-tint);
  border-radius: 9999px;
  vertical-align: baseline;
  white-space: nowrap;
  line-height: 1.5;
}

.link-pill--chip .link-pill__label {
  display: inline-block;
  max-width: 24ch;
  overflow: hidden;
  text-overflow: ellipsis;
  vertical-align: bottom;
}

.link-pill--chip .link-pill__icon,
.link-pill--chip .link-pill__avatar {
  margin-right: 0.3em;
  vertical-align: -0.15em;
}

@media (hover: hover) {
  .link-pill--inline:hover {
    text-decoration-thickness: 2px;
  }

  .link-pill--chip:hover {
    border-color: var(--link-pill-tint);
    background-color: rgba(0, 0, 0, 0.04);
  }

  .dark .link-pill--chip:hover {
    background-color: rgba(255, 255, 255, 0.08);
  }
}

@supports (color: color-mix(in srgb, red, red)) {
  .link-pill--inline {
    text-decoration-color: color-mix(in srgb, var(--link-pill-tint) 55%, transparent);
  }

  .link-pill--inline:hover {
    text-decoration-color: var(--link-pill-tint);
  }

  .link-pill--chip {
    border-color: color-mix(in srgb, var(--link-pill-tint) 28%, transparent);
    background-color: color-mix(in srgb, var(--link-pill-tint) 10%, transparent);
  }

  @media (hover: hover) {
    .link-pill--chip:hover,
    .dark .link-pill--chip:hover {
      border-color: color-mix(in srgb, var(--link-pill-tint) 55%, transparent);
      background-color: color-mix(in srgb, var(--link-pill-tint) 18%, transparent);
    }
  }
}
